-- v9: book summaries. Instead of reading whole books, one detailed summary per day, in a fixed
-- order. The plan is loaded once from data/books/summaries.yaml and edited on the dashboard.
-- Day N of the plan shows the book at position N. Summaries are generated by the Claude API.
CREATE TABLE IF NOT EXISTS book_plan (
  id        SERIAL PRIMARY KEY,
  position  INT NOT NULL,
  title     TEXT NOT NULL,
  author    TEXT NOT NULL DEFAULT '',
  category  TEXT NOT NULL DEFAULT '',
  why       TEXT NOT NULL DEFAULT '',   -- what you want from this book
  added_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT book_plan_position UNIQUE (position) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS book_summaries (
  book_id      INT PRIMARY KEY REFERENCES book_plan(id) ON DELETE CASCADE,
  summary      JSONB NOT NULL DEFAULT '{}',
  model        TEXT NOT NULL DEFAULT '',
  status       TEXT NOT NULL DEFAULT 'ready',  -- ready | error
  error        TEXT NOT NULL DEFAULT '',
  generated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  read_at      TIMESTAMPTZ,                    -- set when you mark it read
  rating       INT,                            -- 1 to 5, how useful it was
  note         TEXT NOT NULL DEFAULT ''        -- what you will apply
);
-- kv keys added: book_summaries (start_date, words, style, language, priority, reader, categories)
